import { test, expect } from '@playwright/test';
import {
	applyConfigOverrides,
	getCompanyDummyConfigOverrides,
	resetDataModel,
	restoreConfig,
	type DataModelPayload,
} from './helpers';

// Requires dbt_company_dummy/target/{manifest,catalog}.json (generated by the e2e bootstrap / CI).
const API_URL = 'http://127.0.0.1:8000/api';
const MODEL_ID = 'model.company_dummy.dim_customer';

const SEEDED_MODEL: DataModelPayload = {
	version: 0.1,
	entities: [
		{
			id: 'dim_customer',
			label: 'Dim Customer',
			dbt_model: MODEL_ID,
		},
	],
	relationships: [],
};

test.describe.configure({ mode: 'serial' });

test.describe('Lineage modal', () => {
	let originalConfig: Record<string, any>;

	test.beforeEach(async ({ request }) => {
		originalConfig = await applyConfigOverrides(request, {
			...getCompanyDummyConfigOverrides(),
			lineage: { enabled: true },
		});
		await resetDataModel(request, SEEDED_MODEL);
	});

	test.afterEach(async ({ request }) => {
		await resetDataModel(request);
		await restoreConfig(request, originalConfig);
	});

	async function openLineage(page: import('@playwright/test').Page) {
		await page.goto('/canvas');
		await page.waitForSelector('[data-testid="canvas-ready"]', { timeout: 30000 });
		const lineageButton = page.getByRole('button', { name: `Show lineage for ${MODEL_ID}`, exact: true });
		await expect(lineageButton).toBeVisible({ timeout: 15000 });
		await lineageButton.click();
		const dialog = page.getByRole('dialog', { name: 'Upstream Lineage' });
		await expect(dialog).toBeVisible({ timeout: 10000 });
		return dialog;
	}

	test('shows the bound model and its upstream models from the lineage API', async ({ page, request }) => {
		const res = await request.get(`${API_URL}/lineage/${encodeURIComponent(MODEL_ID)}`);
		expect(res.ok()).toBeTruthy();
		const lineage = await res.json();
		const root = lineage.nodes.find((n: any) => n.id === lineage.metadata.root_model_id);
		const directParents = lineage.edges
			.filter((e: any) => e.target === root.id)
			.map((e: any) => lineage.nodes.find((n: any) => n.id === e.source));
		expect(directParents.length).toBeGreaterThan(0);

		const dialog = await openLineage(page);

		await expect(dialog.getByText(MODEL_ID)).toBeVisible();
		await expect(dialog.getByText('Generating lineage...')).toBeHidden({ timeout: 15000 });
		await expect(dialog.getByText(root.label, { exact: true })).toBeVisible();
		for (const parent of directParents) {
			await expect(dialog.getByText(parent.label, { exact: true }).first()).toBeVisible();
		}
		await expect(dialog.locator('.svelte-flow__edge').first()).toBeAttached();
	});

	test('closes with the Close button and with Escape', async ({ page }) => {
		const dialog = await openLineage(page);

		await dialog.getByRole('button', { name: 'Close' }).click();
		await expect(dialog).toBeHidden();

		await page.getByRole('button', { name: `Show lineage for ${MODEL_ID}`, exact: true }).click();
		await expect(dialog).toBeVisible();
		await page.keyboard.press('Escape');
		await expect(dialog).toBeHidden();
	});
});
